import {content} from './content-4dc2c046038b.js';
export const email='emiliozarinangomez@gmail.com';
export const portraitSrc='assets/emilio-zarinan.jpg';
export const escapeHTML=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const e=escapeHTML;
const ids=['inicio','trayectoria','proyectos','capacidades'];
const tokens=tools=>`<ul class="tokens">${tools.map(tool=>`<li>${e(tool)}</li>`).join('')}</ul>`;
export function renderProject(t,project,index,total){const p=t.projects;return `<div class="case-head"><span class="eyebrow">${e(project.type)}</span><span class="case-index">${e(p.position)} ${index+1} ${e(p.of)} ${total}</span></div><h3>${e(project.question)}</h3><p class="case-summary">${e(project.summary)}</p><div class="case-flow" aria-hidden="true">${project.flow.map((label,i)=>`<span>${e(label)}</span>${i<2?'<b>→</b>':''}`).join('')}</div><div class="case-story"><section><span class="case-step">01</span><div><h4>${e(p.challenge)}</h4><p>${e(project.challenge)}</p></div></section><section><span class="case-step">02</span><div><h4>${e(p.contribution)}</h4><p>${e(project.contribution)}</p></div></section><section><span class="case-step">03</span><div><h4>${e(p.outcome)}</h4><p>${e(project.outcome)}</p></div></section></div>${project.survey?`<details class="survey"><summary>${e(p.survey)}<span aria-hidden="true">＋</span></summary><div class="survey-content"><div class="survey-sample"><span>${e(project.survey.users)}</span><span>${e(project.survey.responses)}</span></div><p>${e(project.survey.result)}</p><p>${e(project.survey.saving)}</p><details><summary>${e(p.method)}</summary><p>${e(p.methodText)}</p></details></div></details>`:''}<div class="case-tools"><span>${e(p.stack)}</span>${tokens(project.tools)}</div><div class="case-pager" hidden><button data-case-prev ${index===0?'disabled':''}>← ${e(p.previous)}</button><span>${String(index+1).padStart(2,'0')} / ${String(total).padStart(2,'0')}</span><button data-case-next ${index===total-1?'disabled':''}>${e(p.next)} →</button></div>`;}
export function renderPage(language='es'){
 const t=content[language]||content.es,h=t.hero,j=t.journey,p=t.projects,a=t.abilities,c=t.contactSection;
 return `<a class="skip-link" href="#contenido">${e(t.skip)}</a><div class="reading-progress" aria-hidden="true"><span></span></div><header class="site-header"><div class="container header-inner"><a class="brand" href="#inicio" aria-label="Emilio Zariñan"><span class="brand-icon" aria-hidden="true">ez<span>.</span></span><span>Emilio Zariñan</span></a><nav aria-label="${e(t.navigation)}">${ids.slice(1).map((id,i)=>`<a href="#${id}">${e(t.nav[i+1])}</a>`).join('')}</nav><div class="header-actions"><button id="language-toggle" hidden type="button" aria-label="${e(t.language)}" title="${e(t.language)}"><span aria-hidden="true">◎</span> ${e(t.languageLabel)}</button><a class="contact-link" href="mailto:${email}">${e(t.contact)} ↗</a></div></div></header>
 <main id="contenido"><section class="hero" id="inicio" data-chapter="0"><div class="container hero-grid"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span>${e(h.label)}</p><p class="hero-name">Emilio Zariñan</p><h1>${e(h.heading)} <br><em>${e(h.accent)}</em></h1><p class="hero-role">${e(h.role)}</p><p class="hero-intro">${e(h.intro)}</p><div class="hero-actions"><a class="button primary" href="#trayectoria">${e(h.start)} <span>↓</span></a><a class="text-link" href="mailto:${email}">${e(h.email)} ↗</a></div></div><figure class="portrait-frame ${portraitSrc?'has-photo':'portrait-pending'}">${portraitSrc?`<img src="${e(portraitSrc)}" alt="${e(h.portraitAlt)}" width="1122" height="1402" fetchpriority="high">`:`<div class="portrait-identity" aria-hidden="true"><span class="portrait-initials">EZ<span>.</span></span><div class="portrait-grid"></div><span class="identity-coordinate">ESCOM / IPN · 2022</span></div>`}<span class="portrait-corner top" aria-hidden="true"></span><span class="portrait-corner bottom" aria-hidden="true"></span><figcaption><span>${e(h.portraitCaption)}</span><small>${e(h.identity)}</small></figcaption><div class="portrait-note"><span class="eyebrow">${e(h.current)}</span><strong>${e(h.position)}</strong><small>${e(h.place)}</small></div></figure></div><div class="container hero-bottom"><span>${e(h.scroll)}</span><span aria-hidden="true">01 — 04 <b>↓</b></span></div></section>
 <section class="journey-section chapter-section" id="trayectoria" data-chapter="1"><div class="container journey-grid"><div class="chapter-intro sticky-intro"><p class="eyebrow">${e(j.label)}</p><h2>${e(j.heading)}</h2><p>${e(j.intro)}</p><div class="journey-marker" aria-hidden="true"><span class="marker-index">01</span><div><small>${e(t.chapter)}</small><span class="marker-title">${e(j.timeline[0].role)}</span></div></div><a class="chapter-next" href="#proyectos">${e(t.next)} <span>↘</span></a></div><div class="timeline">${j.timeline.map((item,i)=>`<article class="timeline-item" data-timeline="${i}"><span class="timeline-node" aria-hidden="true"></span><div class="timeline-date">${e(item.year)}</div><span class="timeline-organization">${e(item.name)}</span><h3>${e(item.role)}</h3><p>${e(item.text)}</p>${item.name==='Vantive'?`<details class="work-details"><summary>${e(j.workTitle)}<span>＋</span></summary><ul>${j.work.map(task=>`<li>${e(task)}</li>`).join('')}</ul></details>`:''}</article>`).join('')}<p class="journey-bridge">${e(j.bridge)} <span aria-hidden="true">↘</span></p></div></div></section>
 <section class="projects-section chapter-section" id="proyectos" data-chapter="2"><div class="container"><div class="section-heading"><p class="eyebrow">${e(p.label)}</p><h2>${e(p.heading)}</h2><p>${e(p.intro)}</p></div><div class="project-filters" hidden role="group" aria-label="${e(p.filterLabel)}">${p.filters.map(([key,label])=>`<button data-filter="${key}" aria-pressed="${key==='all'}">${e(label)}</button>`).join('')}</div><div class="project-workspace"><div class="project-index" hidden><span class="project-count" role="status" aria-live="polite">6 ${e(p.count)}</span><div class="project-list" role="group" aria-label="${e(p.selectionLabel)}">${p.items.map((item,i)=>`<button class="project-selector" data-project="${item.id}" aria-pressed="${i===0}" aria-controls="case-panel"><span class="project-number">${String(i+1).padStart(2,'0')}</span><span><strong>${e(item.name)}</strong><small>${e(item.type)}</small></span><b aria-hidden="true">↗</b></button>`).join('')}</div></div><article class="case-panel" id="case-panel" tabindex="-1" aria-label="${e(p.items[0].name)}">${renderProject(t,p.items[0],0,p.items.length)}</article></div><noscript><div class="no-script-projects">${p.items.slice(1).map(item=>`<details><summary>${e(item.name)}</summary><p>${e(item.summary)}</p><p>${e(item.contribution)}</p></details>`).join('')}</div></noscript><a class="chapter-next" href="#capacidades">${e(t.next)} <span>↘</span></a></div></section>
 <section class="abilities-section chapter-section" id="capacidades" data-chapter="3"><div class="container"><div class="section-heading"><p class="eyebrow">${e(a.label)}</p><h2>${e(a.heading)}</h2><p>${e(a.intro)}</p></div><div class="professional-block"><div class="professional-heading"><span class="small-label">${e(a.humanLabel)}</span><h3>${e(a.professional)}</h3><p>${e(a.professionalIntro)}</p></div><div><ul class="professional-skills">${a.skills.map((skill,i)=>`<li><span aria-hidden="true">${String(i+1).padStart(2,'0')}</span>${e(skill)}</li>`).join('')}</ul><div class="skills-stories">${a.skillsStories.map((story,i)=>`<details><summary><span class="story-symbol" aria-hidden="true">${['◇','↗','✓'][i]}</span>${e(story.title)}<b aria-hidden="true">＋</b></summary><p>${e(story.text)}</p></details>`).join('')}</div></div></div><div class="technical-heading"><span class="small-label">${e(a.techLabel)}</span><h3>${e(a.technical)}</h3></div><div class="skills-grid">${a.groups.map(group=>`<article class="skill-card tone-${group.tone}"><span class="skill-symbol" aria-hidden="true">${e(group.symbol)}</span><h4>${e(group.title)}</h4>${group.tools.length?tokens(group.tools):''}<p>${e(group.text)}</p>${group.level?`<span class="skill-level">${e(group.level)}</span>`:''}</article>`).join('')}</div><div class="ability-bottom"><div class="ai-note"><span aria-hidden="true">✧</span><div><h3>${e(a.aiTitle)}</h3><p>${e(a.aiText)}</p></div></div><div class="languages"><span class="small-label">${e(a.languages)}</span><p>${e(a.spanish)}</p><p>${e(a.english)}</p></div></div></div></section>
 <section class="contact-section" id="contacto"><div class="container contact-grid"><div><p class="eyebrow">${e(c.label)}</p><h2>${e(c.heading)}</h2><p>${e(c.text)}</p></div><div class="contact-actions"><span class="small-label">${e(c.action)}</span><a class="email-link" href="mailto:${email}">${email}<span aria-hidden="true">↗</span></a><button id="copy-email" hidden>${e(c.copy)} <span aria-hidden="true">⧉</span></button><p id="copy-status" role="status" aria-live="polite"></p></div></div></section></main><footer><div class="container"><span>© ${new Date().getFullYear()} ${e(t.footer)}</span><a href="#inicio">${e(t.backTop)} ↑</a></div></footer><div class="chapter-dock" aria-label="${e(t.storyLabel)}"><span class="dock-caption">${e(t.reader)}</span>${ids.map((id,i)=>`<a href="#${id}" ${i===0?'aria-current="location"':''}><span class="dock-number">0${i+1}</span><span class="dock-label">${e(t.nav[i])}</span></a>`).join('')}</div><div class="visually-hidden" id="language-status" role="status" aria-live="polite"></div>`.replaceAll('↗', '<svg class="arrow-icon" width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" aria-hidden="true"><path d="M3 13 13 3M3 3h10v10"/></svg>');
}
